export type Notification = {
  __typename: 'Notification';
  created: Scalars['Time']['output'];
  data: NotificationData;
  level: NotificationLevel;
  read: Scalars['Boolean']['output'];
};

export type NotificationData = CommentCommentedEdit | CommentOwnEdit | CommentVotedEdit | DownvoteOwnEdit | FailedOwnEdit | FavoritePerformerEdit | FavoritePerformerScene | FavoriteStudioEdit | FavoriteStudioScene | FingerprintMovedScene | FingerprintedSceneEdit | SavedSearchMatch | UpdatedEdit;

export enum NotificationEnum {
  COMMENT_COMMENTED_EDIT = 'COMMENT_COMMENTED_EDIT',
  COMMENT_OWN_EDIT = 'COMMENT_OWN_EDIT',
  COMMENT_VOTED_EDIT = 'COMMENT_VOTED_EDIT',
  DOWNVOTE_OWN_EDIT = 'DOWNVOTE_OWN_EDIT',
  FAILED_OWN_EDIT = 'FAILED_OWN_EDIT',
  FAVORITE_PERFORMER_EDIT = 'FAVORITE_PERFORMER_EDIT',
  FAVORITE_PERFORMER_SCENE = 'FAVORITE_PERFORMER_SCENE',
  FAVORITE_STUDIO_EDIT = 'FAVORITE_STUDIO_EDIT',
  FAVORITE_STUDIO_SCENE = 'FAVORITE_STUDIO_SCENE',
  FINGERPRINTED_SCENE_EDIT = 'FINGERPRINTED_SCENE_EDIT',
  FINGERPRINT_MOVED = 'FINGERPRINT_MOVED',
  /** A saved search found scenes it had not seen before (one notification per run) */
  SAVED_SEARCH_MATCH = 'SAVED_SEARCH_MATCH',
  UPDATED_EDIT = 'UPDATED_EDIT'
}

export enum NotificationLevel {
  NORMAL = 'NORMAL',
  URGENT = 'URGENT'
}

/** What may be exchanged with a peer, decided field by field. */
export type OntologyCompatibility = {
  __typename: 'OntologyCompatibility';
  /** Every field of the document, decided -- the closed list, so a caller can tell 'allowed' from 'not asked about'. */
  fields: Array<OntologyFieldDecision>;
  /** Every core version both instances implement, ascending. Empty means the two cannot speak at all. */
  shared: Array<Scalars['Int']['output']>;
};

/**
 * What an instance says about the ontology it speaks (phase 12, slice 12a).
 *
 * It carries no tag names and no edges: see `ontologyDeclaration` in schema.graphql for why the
 * comparison travels as a digest rather than as the document.
 */
export type OntologyDeclaration = {
  __typename: 'OntologyDeclaration';
  /** The core ontology versions this instance implements, ascending. */
  core_versions: Array<Scalars['Int']['output']>;
  /** SHA-256, in hexadecimal, of the canonical implication document. Two instances holding the same ontology agree on it. */
  digest: Scalars['String']['output'];
  /** How many implication edges the document holds. */
  implications: Scalars['Int']['output'];
  /** The version of THIS instance's document. Local: two instances at version 7 hold two different ontologies. */
  local_version: Scalars['Int']['output'];
  /** How many distinct tag names the document mentions. NOT the count of tags: a tag with no implications is not in the document. */
  named_tags: Scalars['Int']['output'];
};

/** One field of the ontology document, and whether it may cross to the peer under discussion. */
export type OntologyFieldDecision = {
  __typename: 'OntologyFieldDecision';
  /** Whether both instances implement `since`. A field only one side implements is not sent, and not dropped either: `reason` says why. */
  allowed: Scalars['Boolean']['output'];
  /** The field's key in the document: tag, implies, category. */
  name: Scalars['String']['output'];
  /** The sentence an operator reads: which version the field needs, and which side lacks it. */
  reason: Scalars['String']['output'];
  /** The core ontology version that introduced the field. */
  since: Scalars['Int']['output'];
};

/** One version of the tag ontology, written when the graph changes. */
export type OntologyVersion = {
  __typename: 'OntologyVersion';
  created: Scalars['Time']['output'];
  note?: Maybe<Scalars['String']['output']>;
  /** The whole ontology at this version, as a JSON list of {"tag": ..., "implies": ...} pairs by name. Empty for a listing. */
  snapshot?: Maybe<Scalars['String']['output']>;
  version: Scalars['Int']['output'];
};

export enum OperationEnum {
  CREATE = 'CREATE',
  DESTROY = 'DESTROY',
  MERGE = 'MERGE',
  MODIFY = 'MODIFY'
}

export type Performer = {
  __typename: 'Performer';
  age?: Maybe<Scalars['Int']['output']>;
  aliases: Array<Scalars['String']['output']>;
  band_size?: Maybe<Scalars['Int']['output']>;
  birth_date?: Maybe<Scalars['String']['output']>;
  /** @deprecated Please use `birth_date` */
  birthdate?: Maybe<FuzzyDate>;
  breast_type?: Maybe<BreastTypeEnum>;
  career_end_year?: Maybe<Scalars['Int']['output']>;
  career_start_year?: Maybe<Scalars['Int']['output']>;
  /**
   * How complete this performer is.
   *
   * Reads the database on demand rather than being stored, so it is correct the
   * moment an edit lands rather than whenever something remembered to refresh it.
   */
  completion?: Maybe<Completion>;
  country?: Maybe<Scalars['String']['output']>;
  created: Scalars['Time']['output'];
  cup_size?: Maybe<Scalars['String']['output']>;
  death_date?: Maybe<Scalars['String']['output']>;
  deleted: Scalars['Boolean']['output'];
  disambiguation?: Maybe<Scalars['String']['output']>;
  edits: Array<Edit>;
  ethnicity?: Maybe<EthnicityEnum>;
  eye_color?: Maybe<EyeColorEnum>;
  gender?: Maybe<GenderEnum>;
  genitals?: Maybe<GenitalEnum>;
  hair_color?: Maybe<HairColorEnum>;
  /** Height in cm */
  height?: Maybe<Scalars['Int']['output']>;
  hip_size?: Maybe<Scalars['Int']['output']>;
  id: Scalars['ID']['output'];
  images: Array<Image>;
  is_favorite: Scalars['Boolean']['output'];
  /** @deprecated Use individual fields, cup/band/waist/hip_size */
  measurements: Measurements;
  /** IDs of performers that were merged into this one */
  merged_ids: Array<Scalars['ID']['output']>;
  /** ID of performer that replaces this one */
  merged_into_id?: Maybe<Scalars['ID']['output']>;
  name: Scalars['String']['output'];
  /** Length in cm */
  penis_length?: Maybe<Scalars['Int']['output']>;
  piercings?: Maybe<Array<BodyModification>>;
  /** Paginated scenes, filtered on top of the ones this performer appears in */
  queryScenes: QueryScenesResultType;
  /** The rating summary rendered next to the performer. */
  reviewSummary: ReviewSummary;
  /**
   * Published reviews, newest first.
   *
   * An empty list is normal and not an error: most performers have no reviews, and a
   * brand-new site having an error here would be a broken page rather than an exceptional
   * condition.
   */
  reviews: Array<Review>;
  scene_count: Scalars['Int']['output'];
  scenes: Array<Scene>;
  /**
   * How many performers clear the shared-scene floor for this one.
   *
   * Separate from `similarPerformers` because that list is limited to a page, while "12
   * performers qualify and you are showing 10" is information a client needs and cannot
   * get from the list alone.
   */
  similarPerformerCount: Scalars['Int']['output'];
  /**
   * Performers who appear alongside this one, most alike first.
   *
   * An empty list is normal and not an error: a performer with no scenes, or one who has
   * never shared two scenes with anybody, has no similar performers on this instance.
   * That is a fact about the archive, not a failure.
   *
   * Excludes this performer and soft-deleted performers, and never returns a performer
   * who shares fewer than `minShared` scenes.
   */
  similarPerformers: Array<SimilarPerformer>;
  studios: Array<PerformerStudio>;
  tattoos?: Maybe<Array<BodyModification>>;
  thumbnail?: Maybe<Image>;
  /**
   * Appearance history by year. Empty for a performer with no dated appearances, which is
   * not an error.
   */
  timeline?: Maybe<PerformerTimeline>;
  updated: Scalars['Time']['output'];
  urls: Array<Url>;
  waist_size?: Maybe<Scalars['Int']['output']>;
  /** Weight in kg */
  weight?: Maybe<Scalars['Int']['output']>;
};


